using System;using System.IO;using System.Runtime.InteropServices;
namespace BeamScheduleFormatter {
sealed class ExcelLiveLink:IDisposable {
 dynamic app,book;bool isolated,freshWorkbook;public string PathName{get;private set;}
 internal static int WorkbookFormat(string path){string extension=Path.GetExtension(path).ToLowerInvariant();if(extension==".xlsm")return 52;if(extension==".xlsx")return 51;throw new Exception("Use an .xlsm or .xlsx Excel workbook.");}
 public ExcelLiveLink(string path,bool visible=true,bool requireTemplate=true){PathName=Path.GetFullPath(path);int format=WorkbookFormat(PathName);isolated=!visible;string template=null;try{var type=Type.GetTypeFromProgID("Excel.Application");if(type==null)throw new Exception("Install desktop Microsoft Excel to use the live workbook link.");if(visible){try{app=Marshal.GetActiveObject("Excel.Application");}catch(COMException){}}if(app==null)app=Activator.CreateInstance(type);foreach(dynamic candidate in app.Workbooks){if(string.Equals((string)candidate.FullName,PathName,StringComparison.OrdinalIgnoreCase)){book=candidate;break;}}if(book==null){int security=Convert.ToInt32(app.AutomationSecurity);bool events=Convert.ToBoolean(app.EnableEvents);try{app.AutomationSecurity=3;app.EnableEvents=false;if(!File.Exists(PathName)){if(requireTemplate){template=Path.Combine(Path.GetTempPath(),"DTCE-template-"+Guid.NewGuid().ToString("N")+".xlsx");using(var input=typeof(ExcelLiveLink).Assembly.GetManifestResourceStream("BeamSummaryTemplate.xlsx"))using(var output=File.Create(template)){if(input==null)throw new Exception("Excel template resource missing.");input.CopyTo(output);}book=app.Workbooks.Open(template,0,false);}else{book=app.Workbooks.Add(-4167);freshWorkbook=true;}book.SaveAs(PathName,format);}else book=app.Workbooks.Open(PathName,0,false);}finally{app.AutomationSecurity=security;app.EnableEvents=events;}}if((bool)book.ReadOnly)throw new Exception("The linked Excel workbook is read-only.");if(requireTemplate&&Convert.ToString(book.Worksheets["RawData"].Range["N1"].Value2)!="BeamToolsSummaryV1")throw new Exception("Choose a Beam/Slab Summary workbook created by this app, or link your existing workbook from Program of Works.");if(visible)app.Visible=true;}catch{Dispose();throw;}finally{if(template!=null)try{File.Delete(template);}catch{}}}

 public void Update(object[,] rows,string status,string estimateXml=null,object[,] concrete=null){bool events=Convert.ToBoolean(app.EnableEvents);try{app.EnableEvents=false;UpdateCore(rows,status,estimateXml,concrete);}finally{app.EnableEvents=events;}}
 void UpdateCore(object[,] rows,string status,string estimateXml,object[,] concrete){dynamic raw=book.Worksheets["RawData"],table=raw.ListObjects["BeamData"];int old=(int)table.Range.Rows.Count;raw.Range["A2:L"+Math.Max(2,old)].ClearContents();int count=rows.GetLength(0);table.Resize(raw.Range["A1:L"+(Math.Max(1,count)+1)]);if(count>0){raw.Range["A2:C"+(count+1)].NumberFormat="@";raw.Range["A2:L"+(count+1)].Value2=rows;}else raw.Range["D2:L2"].Value2=0;raw.Range["F2:K"+(Math.Max(1,count)+1)].NumberFormat="0.00";book.Worksheets["Summary"].Range["B3"].Value2=status;book.Worksheets["Summary"].Range["B4"].Value2="Updated: "+DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");if(concrete!=null)WriteConcrete(concrete,status.Contains("Slab purchase"));if(estimateXml!=null)WriteEstimate(estimateXml);app.CalculateFull();book.Save();}
 void WriteConcrete(object[,] rows,bool slab=false){string sheetName=slab?"SlabConcreteFormwork":"BeamConcreteFormwork",marker=slab?"DTCESlabMeasuresV1":"DTCEBeamMeasuresV1";dynamic sheet=null;foreach(dynamic candidate in book.Worksheets)if((string)candidate.Name==sheetName){sheet=candidate;break;}if(sheet==null){sheet=book.Worksheets.Add();sheet.Name=sheetName;}else if(Convert.ToString(sheet.Range["J1"].Value2)!=marker)throw new Exception("Existing BeamConcreteFormwork sheet is not owned by this app; it was not overwritten.");sheet.Range["A:H"].ClearContents();sheet.Range["J1"].Value2=marker;var names=new object[1,8]{{"Description",slab?"Slab":"Beam","Support","Quantity","Concrete m3 (gross)",slab?"Cantilever edge forms m2":"Side forms m2","Bottom forms m2","Total forms m2"}};sheet.Range["A1:H1"].Value2=names;int count=rows.GetLength(0);if(count>0)sheet.Range["A2:H"+(count+1)].Value2=rows;sheet.Range["E2:H"+(Math.Max(1,count)+1)].NumberFormat="0.00";int total=count+3;sheet.Cells[total,1].Value2="TOTAL";foreach(string column in new[]{"E","F","G","H"})sheet.Range[column+total].Formula="=SUM("+column+"2:"+column+(Math.Max(1,count)+1)+")";sheet.Range["E"+total+":H"+total].NumberFormat="0.00";sheet.Range["A:H"].Columns.AutoFit();}
 dynamic NewOutputSheet(string name){dynamic sheet;if(freshWorkbook&&(int)book.Worksheets.Count==1){sheet=book.Worksheets[1];freshWorkbook=false;}else sheet=book.Worksheets.Add();sheet.Name=name;return sheet;}
 const string EstimateSheet="DTCE_Estimate";
 dynamic FindEstimateSheet(string name=EstimateSheet){foreach(dynamic sheet in book.Worksheets)if((string)sheet.Name==name)return sheet;return null;}
 public string ReadEstimate(){return ReadSnapshot(EstimateSheet);}
 public string ReadWorksProject(){return ReadSnapshot("DTCE_POW_Project");}
 string ReadSnapshot(string name){dynamic sheet=FindEstimateSheet(name);if(sheet==null)return null;if(Convert.ToString(sheet.Range["A1"].Value2)!=ExcelEstimateData.Marker)throw new Exception("Reserved estimate sheet has unrecognized content; it was not overwritten.");int count;if(!int.TryParse(Convert.ToString(sheet.Range["A2"].Value2),out count)||count<1||count>5000)throw new Exception("Invalid saved estimate chunk count.");var chunks=new string[count];for(int n=0;n<count;n++)chunks[n]=Convert.ToString(sheet.Cells[n+3,1].Value2);return ExcelEstimateData.Unpack(chunks);}
 void WriteEstimate(string xml,string name=EstimateSheet,string activate="Summary"){string[] chunks=ExcelEstimateData.Pack(xml);dynamic sheet=FindEstimateSheet(name);if(sheet==null){sheet=book.Worksheets.Add();sheet.Name=name;}else if(Convert.ToString(sheet.Range["A1"].Value2)!=ExcelEstimateData.Marker)throw new Exception("Reserved estimate sheet has unrecognized content; it was not overwritten.");sheet.UsedRange.ClearContents();sheet.Range["A1:A"+(chunks.Length+2)].NumberFormat="@";sheet.Range["A1"].Value2=ExcelEstimateData.Marker;sheet.Range["A2"].Value2=chunks.Length.ToString();var values=new object[chunks.Length,1];for(int n=0;n<chunks.Length;n++)values[n,0]=chunks[n];sheet.Range["A3:A"+(chunks.Length+2)].Value2=values;book.Worksheets[activate].Activate();sheet.Visible=2;}
 public void UpdateWorks(System.Collections.Generic.List<WorksExcelTable> tables,string xml){bool events=Convert.ToBoolean(app.EnableEvents);try{app.EnableEvents=false;UpdateWorksCore(tables,xml);}finally{app.EnableEvents=events;}}
 public void UpdateWorksQuantities(System.Collections.Generic.List<WorksExcelTable> tables){UpdateWorks(tables,null);}
 void UpdateWorksCore(System.Collections.Generic.List<WorksExcelTable> tables,string xml){
  // Verify ownership of every reserved sheet before changing any cell.
  foreach(var table in tables){dynamic existing=FindEstimateSheet(table.Name);if(existing!=null&&Convert.ToString(existing.Range["AA1"].Value2)!="DTCEProgramOfWorksV1:"+table.Name)throw new Exception("Sheet '"+table.Name+"' is not owned by Program of Works. Rename it or choose another workbook.");}
  dynamic project=FindEstimateSheet("DTCE_POW_Project");if(xml!=null&&project!=null&&Convert.ToString(project.Range["A1"].Value2)!=ExcelEstimateData.Marker)throw new Exception("Reserved project sheet has unrecognized content.");
  dynamic footingSheet=FindEstimateSheet(WorksSummaryLayout.Sheet);if(footingSheet!=null&&Convert.ToString(footingSheet.Range["AA3"].Value2)!="DTCEFootingSummaryV1")for(int r=33;r<=35;r++)for(int c=1;c<=3;c++)if(!string.IsNullOrEmpty(Convert.ToString(footingSheet.Cells[r,c].Value2)))throw new Exception("Footing summary needs reserved cells A33:C35, but these contain custom data. Move that data or choose another workbook.");
  // Catalog output occupies a new bounded block; never overwrite pre-existing custom cells.
  dynamic summary=FindEstimateSheet(WorksSummaryLayout.Sheet),legacy=FindEstimateSheet("POW Summary");dynamic catalogSheet=summary;if(catalogSheet==null&&legacy!=null&&Convert.ToString(legacy.Range["AA1"].Value2)=="DTCEProgramOfWorksV1:POW Summary")catalogSheet=legacy;
  if(tables.Exists(t=>t.Name==WorksSummaryLayout.Sheet&&t.StartColumn==4)&&catalogSheet!=null&&Convert.ToString(catalogSheet.Range["AA2"].Value2)!=FinishTypeCatalog.Schema)for(int r=FinishTypeCatalog.HeaderRow;r<=FinishTypeCatalog.LastRow;r++)for(int c=4;c<=6;c++)if(!string.IsNullOrEmpty(Convert.ToString(catalogSheet.Cells[r,c].Value2)))throw new Exception("Finish totals need reserved cells D35:F56, but these contain custom data. Move that data or choose a new workbook.");
  if(tables.Exists(t=>t.Name==WorksSummaryLayout.Sheet&&t.StartColumn==8)&&summary!=null&&Convert.ToString(summary.Range["AA4"].Value2)!="DTCEFinalQuantitiesV1")for(int row=1;row<=200;row++)for(int col=8;col<=10;col++)if(!string.IsNullOrEmpty(Convert.ToString(summary.Cells[row,col].Value2)))throw new Exception("Final quantities need cells H1:J200, but these contain custom data. Move the data or choose another workbook.");
  if(xml!=null)ExcelEstimateData.Pack(xml);if(summary==null&&legacy!=null&&Convert.ToString(legacy.Range["AA1"].Value2)=="DTCEProgramOfWorksV1:POW Summary"){legacy.Name=WorksSummaryLayout.Sheet;legacy.Range["AA1"].Value2="DTCEProgramOfWorksV1:"+WorksSummaryLayout.Sheet;}
  foreach(var table in tables){dynamic sheet=FindEstimateSheet(table.Name);if(sheet==null)sheet=NewOutputSheet(table.Name);int sr=table.StartRow,sc=table.StartColumn,cols=table.Headers.Length,count=table.Rows.GetLength(0),last=sr+count;
   if(table.Name==WorksSummaryLayout.Sheet){if(sc==1){sheet.Range["A1:C"+WorksSummaryLayout.LastRow].ClearContents();sheet.Range["AA3"].Value2="DTCEFootingSummaryV1";}else if(sc==4){sheet.Range["D35:F56"].ClearContents();sheet.Range["AA2"].Value2=FinishTypeCatalog.Schema;}else if(sc==8){sheet.Range["H1:J200"].ClearContents();sheet.Range["AA4"].Value2="DTCEFinalQuantitiesV1";}}else sheet.UsedRange.ClearContents();sheet.Range["AA1"].Value2="DTCEProgramOfWorksV1:"+table.Name;var headers=new object[1,cols];for(int c=0;c<cols;c++)headers[0,c]=table.Headers[c];sheet.Range[sheet.Cells[sr,sc],sheet.Cells[sr,sc+cols-1]].Value2=headers;sheet.Range[sheet.Cells[sr,sc],sheet.Cells[sr,sc+cols-1]].Font.Bold=true;
   if(count>0){dynamic data=sheet.Range[sheet.Cells[sr+1,sc],sheet.Cells[last,sc+cols-1]];data.NumberFormat="0.00";for(int c=0;c<cols;c++){bool text=false,whole=true;for(int r=0;r<count;r++){object v=table.Rows[r,c];if(v is string)text=true;if(v!=null&&!(v is int)&&!(v is long))whole=false;}dynamic column=sheet.Range[sheet.Cells[sr+1,sc+c],sheet.Cells[last,sc+c]];if(text)column.NumberFormat="@";else if(whole)column.NumberFormat="0";}data.Value2=table.Rows;}
   sheet.Range[sheet.Cells[sr,sc],sheet.Cells[Math.Max(sr,last),sc+cols-1]].Columns.AutoFit();
  }
  if(xml!=null)WriteEstimate(xml,"DTCE_POW_Project",WorksSummaryLayout.Sheet);else book.Worksheets[WorksSummaryLayout.Sheet].Activate();app.CalculateFull();book.Save();
 }
 static string[] DesignNames(string kind){if(kind=="Purlin-Design")return new[]{"DTCE Purlin Design","DTCE_Design_Purlin"};if(kind=="Truss-Connections")return new[]{"DTCE Truss Connections","DTCE_Design_Truss"};throw new Exception("Unsupported design sheet type.");}
 public void UpdateDesignReport(string kind,string report){var names=DesignNames(kind);string marker="DTCEDesignReportV1:"+kind;dynamic existing=FindEstimateSheet(names[0]);if(existing!=null&&Convert.ToString(existing.Range["AA1"].Value2)!=marker)throw new Exception("Existing design report sheet is not owned by this app.");bool events=Convert.ToBoolean(app.EnableEvents);try{app.EnableEvents=false;dynamic sheet=existing;if(sheet==null)sheet=NewOutputSheet(names[0]);sheet.UsedRange.ClearContents();sheet.Range["AA1"].Value2=marker;string[] lines=report.Replace("\r","").Split('\n');var rows=new object[lines.Length,1];for(int n=0;n<lines.Length;n++)rows[n,0]=lines[n];sheet.Range["A1:A"+lines.Length].NumberFormat="@";sheet.Range["A1:A"+lines.Length].Value2=rows;sheet.Range["A1:A"+lines.Length].ColumnWidth=110;sheet.Range["A1:A"+lines.Length].WrapText=true;sheet.Range["A1:A"+lines.Length].Rows.AutoFit();sheet.Activate();book.Save();}finally{app.EnableEvents=events;}}
 public double Value(string cell){return Convert.ToDouble(book.Worksheets["Summary"].Range[cell].Value2);}
 public void Dispose(){try{if(isolated&&book!=null)book.Close(false);}catch{}try{if(isolated&&app!=null)app.Quit();}catch{}if(book!=null&&Marshal.IsComObject(book))Marshal.ReleaseComObject(book);if(app!=null&&Marshal.IsComObject(app))Marshal.ReleaseComObject(app);book=null;app=null;}
}
}
